            S1paVg==
            """
        guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters), let text = String(data: data, encoding: .utf8) else { return [:] }
        return Dictionary(uniqueKeysWithValues: text.split(separator: "\n").compactMap { line in
            let pair = line.split(separator: "=", maxSplits: 1).map(String.init)
            return pair.count == 2 ? (pair[0], pair[1]) : nil
        })
    }()
    static func canonical(_ input: String) -> String {
        let code = input.uppercased().filter { $0.isASCII && ($0.isLetter || $0.isNumber) }
        return aliases[code] ?? code
    }
    static func codes(_ text: String) -> [String] {
        text.uppercased().components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { (3...4).contains($0.count) && $0.contains(where: { $0.isLetter }) }.map(canonical)
    }
    static func formatted(_ text: String) -> String {
        codes(text).joined(separator: " → ")
    }
}

enum AirportPreferences {
    static func read(_ input: String, defaults: UserDefaults = .standard) -> (rating: Int, comment: String) {
        let code = AirportRoute.canonical(input)
        let aliases = AirportRoute.aliases.filter { $0.value == code }.map(\.key).sorted()
        let ratingKey = "airportRating-" + code, commentKey = "airportNotes-" + code
        if defaults.object(forKey: ratingKey) == nil,
           let alias = aliases.first(where: { defaults.object(forKey: "airportRating-" + $0) != nil }) {
            defaults.set(defaults.integer(forKey: "airportRating-" + alias), forKey: ratingKey)
        }
        if defaults.object(forKey: commentKey) == nil {
            var seen = Set<String>()
            let notes = aliases.compactMap { defaults.string(forKey: "airportNotes-" + $0) }
                .filter { !$0.isEmpty && seen.insert($0).inserted }
            if !notes.isEmpty { defaults.set(notes.joined(separator: "\n\n"), forKey: commentKey) }
        }
        return (min(5, max(0, defaults.integer(forKey: ratingKey))), defaults.string(forKey: commentKey) ?? "")
    }
}

// MARK: - Airport lookup, route map, and memories

struct AirportInfo: Identifiable, Codable, Sendable {
    var code: String
    var name: String
    var location: String
    var latitude: Double
    var longitude: Double
    var use: String? = nil
    var towered: Bool? = nil
    var elevation: Double? = nil
    var effectiveDate: String? = nil
    var source: String? = nil
    var retrievedAt: Date? = nil
    var id: String { code }
    var coordinate: CLLocationCoordinate2D { CLLocationCoordinate2D(latitude: latitude, longitude: longitude) }
}

// Shared framing for the interactive map and story snapshots. Keep the actual
// stored x value when choosing a wrap boundary; adding a world width then taking
// a remainder introduces rounding that can turn a local route into a world map.
enum AirportMapGeometry {
    static func mapRect(_ coordinates: [CLLocationCoordinate2D], aspectRatio: Double = 1) -> MKMapRect? {
        let coordinates = coordinates.filter { CLLocationCoordinate2DIsValid($0) }
        let points = coordinates.map { MKMapPoint($0) }.filter { $0.x.isFinite && $0.y.isFinite }
        guard !points.isEmpty else { return nil }
        let world = MKMapRect.world.size.width
        let xs = Array(Set(points.map(\.x))).sorted()
        var start = xs[0], largestGap = -Double.infinity
        for index in xs.indices {
            let nextIndex = (index + 1) % xs.count
            let next = xs[nextIndex] + (nextIndex == 0 ? world : 0)
            let gap = next - xs[index]
            if gap > largestGap {
                largestGap = gap
                start = xs[nextIndex]
            }
        }
        let unwrapped = points.map { $0.x < start ? $0.x + world : $0.x }
        let minX = unwrapped.min()!, maxX = unwrapped.max()!
        let minY = points.map(\.y).min()!, maxY = points.map(\.y).max()!
        let latitude = max(-80, min(80, coordinates[coordinates.count / 2].latitude))
        let minimum = 14000 * MKMapPointsPerMeterAtLatitude(latitude)
        var width = max(maxX - minX, minimum) * 1.7
        var height = max(maxY - minY, minimum) * 1.7
        let ratio = max(0.2, min(5, aspectRatio))
        if width / height < ratio { width = height * ratio }
        else { height = width / ratio }
        width = min(world, width); height = min(world, height)
        let centerX = ((minX + maxX) / 2).truncatingRemainder(dividingBy: world)
        let centerY = max(height / 2, min(world - height / 2, (minY + maxY) / 2))
        return MKMapRect(x: centerX - width / 2, y: centerY - height / 2, width: width, height: height)
    }
}

// FAA GIS is the primary source. DOT can supplement tower information. The
// worldwide fallback is used only for airports missing from those inventories.
// All values come from the source responses; unknown fields stay unknown.
enum AirportDataService {
    nonisolated static func faa(_ codes: [String]) async -> [String: AirportInfo] {
        // Keep each query on one identifier field. A combined OR query can scan
        // the whole public inventory and consume its shared request quota.
        async let icao = faaBatch(codes.filter { $0.count == 4 }, field: "ICAO_ID")
        async let local = faaBatch(codes.filter { $0.count == 3 }, field: "IDENT")
        let (icaoAirports, localAirports) = await (icao, local)
        return icaoAirports.merging(localAirports, uniquingKeysWith: { first, _ in first })
    }
    private nonisolated static func faaBatch(_ codes: [String], field: String) async -> [String: AirportInfo] {
        guard !codes.isEmpty else { return [:] }
        let list = codes.map { "'\($0)'" }.joined(separator: ",")
        guard let url = queryURL("https://services6.arcgis.com/ssFJjBXIUyZDrSYZ/ArcGIS/rest/services/US_Airport/FeatureServer/0/query",
            where: "\(field) IN (\(list))", fields: "ICAO_ID,IDENT,NAME,SERVCITY,STATE,COUNTRY,ELEVATION,PRIVATEUSE,TYPE_CODE"),
            let json = await json(url), let rows = json["features"] as? [[String: Any]] else { return [:] }
        return parseFAA(rows, codes: codes)
    }
    nonisolated static func parseFAA(_ rows: [[String: Any]], codes: [String]) -> [String: AirportInfo] {
        var results: [String: AirportInfo] = [:]
        for row in rows {
            guard let attributes = row["attributes"] as? [String: Any], let geometry = row["geometry"] as? [String: Any],
                  let name = string(attributes["NAME"]), let lat = number(geometry["y"]), let lon = number(geometry["x"]),
                  abs(lat) <= 90, abs(lon) <= 180 else { continue }
            let identifiers = [string(attributes["ICAO_ID"]), string(attributes["IDENT"])].compactMap { $0?.uppercased() }
            let privateUse = number(attributes["PRIVATEUSE"])
            let use: String? = privateUse == 0 ? "Public" : privateUse == 1 ? "Private" : nil
            for code in codes where identifiers.contains(code) {
                results[code] = AirportInfo(code: code, name: name,
                    location: [string(attributes["SERVCITY"]), string(attributes["STATE"])].compactMap { $0 }.joined(separator: ", "),
                    latitude: lat, longitude: lon, use: use, elevation: number(attributes["ELEVATION"]),
                    source: "FAA airport data", retrievedAt: Date())
            }
        }
        return results
    }
    nonisolated static func dot(_ codes: [String]) async -> [String: AirportInfo] {
        let list = codes.map { "'\($0)'" }.joined(separator: ",")
        guard let url = queryURL("https://geo.dot.gov/server/rest/services/hosted/Airports_/FeatureServer/0/query",
            where: "icao_identifier IN (\(list))", fields: "icao_identifier,fac_name,city,state_post_office_code,fac_use,atc_tower,elevation"),
            let json = await json(url, timeout: 8), let rows = json["features"] as? [[String: Any]] else { return [:] }
        var results: [String: AirportInfo] = [:]
        for row in rows {
            guard let raw = row["attributes"] as? [String: Any], let geometry = row["geometry"] as? [String: Any] else { continue }
            let a = Dictionary(raw.map { ($0.key.lowercased(), $0.value) }, uniquingKeysWith: { first, _ in first })
            guard let code = string(a["icao_identifier"])?.uppercased(), codes.contains(code),
                  let name = string(a["fac_name"]), let lat = number(geometry["y"]), let lon = number(geometry["x"]),
                  abs(lat) <= 90, abs(lon) <= 180 else { continue }
            let use = string(a["fac_use"])?.uppercased()
            let tower = string(a["atc_tower"])?.uppercased()
            results[code] = AirportInfo(code: code, name: name.capitalized,
                location: [string(a["city"]), string(a["state_post_office_code"])].compactMap { $0 }.joined(separator: ", "),
                latitude: lat, longitude: lon, use: use == "PU" ? "Public" : use == "PR" ? "Private" : nil,
                towered: tower == "Y" ? true : tower == "N" ? false : nil, elevation: number(a["elevation"]),
                source: "U.S. DOT airport inventory", retrievedAt: Date())
        }
        return results
    }
    nonisolated static func fallback(_ code: String) async -> AirportInfo? {
        guard let url = URL(string: "https://airport-data.com/api/ap_info.json?icao=\(code)"),
              let json = await json(url, timeout: 8), let name = string(json["name"]),
              let lat = number(json["latitude"]), let lon = number(json["longitude"]), abs(lat) <= 90, abs(lon) <= 180 else { return nil }
        return AirportInfo(code: code, name: name.capitalized, location: string(json["location"]) ?? "",
            latitude: lat, longitude: lon, elevation: number(json["elevation"]), source: "Airport-Data", retrievedAt: Date())
    }
    nonisolated static func merge(_ primary: AirportInfo, _ supplement: AirportInfo?) -> AirportInfo {
        guard let supplement else { return primary }
        var result = primary
        result.use = primary.use ?? supplement.use
        result.towered = primary.towered ?? supplement.towered
        result.elevation = primary.elevation ?? supplement.elevation
        if primary.towered == nil, supplement.towered != nil { result.source = "FAA / U.S. DOT airport data" }
        return result
    }
    private nonisolated static func queryURL(_ base: String, where condition: String, fields: String) -> URL? {
        var url = URLComponents(string: base)
        url?.queryItems = [URLQueryItem(name: "where", value: condition), URLQueryItem(name: "outFields", value: fields),
            URLQueryItem(name: "outSR", value: "4326"), URLQueryItem(name: "returnGeometry", value: "true"), URLQueryItem(name: "f", value: "json")]
        return url?.url
    }
    private nonisolated static func json(_ url: URL, timeout: Double = 14) async -> [String: Any]? {
        var request = URLRequest(url: url)
        request.timeoutInterval = timeout
        do {
            let (data, response) = try await URLSession.shared.data(for: request)
            guard let http = response as? HTTPURLResponse, (200...299).contains(http.statusCode) else { return nil }
            return try JSONSerialization.jsonObject(with: data) as? [String: Any]
        } catch { return nil }
    }
    private nonisolated static func number(_ value: Any?) -> Double? {
        let number = (value as? NSNumber)?.doubleValue ?? (value as? String).flatMap(Double.init)
        return number.flatMap { $0.isFinite ? $0 : nil }
    }
    private nonisolated static func string(_ value: Any?) -> String? {
        guard let value = value as? String else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }
}

@MainActor final class AirportCatalog: ObservableObject {
    @Published var airports: [String: AirportInfo] = [:]
    @Published private(set) var coordinateRevision = 0
    @Published var loading: Set<String> = []
    @Published var failed: Set<String> = []
    private var requests: [String: Task<Void, Never>] = [:]
    private var freshUntil: [String: Date] = [:]
    func load(_ codes: [String], refresh: Bool = false) async {
        let codes = Array(Set(codes.map(AirportRoute.canonical)))
            .filter { (3...4).contains($0.count) }.sorted()
        for code in codes where airports[code] == nil { restore(code) }
        let pending = codes.filter { requests[$0] == nil && (refresh || (freshUntil[$0] ?? .distantPast) <= Date()) }
        if !pending.isEmpty {
            loading.formUnion(pending); failed.subtract(pending)
            // Unstructured shared work survives a tab switch or a cancelled view task.
            // Other callers join this work instead of dropping an in-flight lookup.
            let job = Task { @MainActor [weak self] in
                guard let self else { return }
                await self.fetch(pending)
                for code in pending { self.requests.removeValue(forKey: code); self.loading.remove(code) }
            }
            for code in pending { requests[code] = job }
        }
        for code in codes {
            guard !Task.isCancelled else { return }
            if let job = requests[code] { await job.value }
        }
    }
    private func restore(_ code: String) {
        for version in [3, 2] {
            guard let data = UserDefaults.standard.data(forKey: "airportInfo-v\(version)-" + code),
                  let info = try? JSONDecoder().decode(AirportInfo.self, from: data), valid(info) else { continue }
            airports[code] = info; coordinateRevision &+= 1
            // Old coordinate-only fallback caches must not prevent the new details lookup.
            if version == 3 { freshUntil[code] = (info.retrievedAt ?? .distantPast).addingTimeInterval(lifetime(info)) }
            return
        }
    }
    private func valid(_ info: AirportInfo) -> Bool { info.latitude.isFinite && info.longitude.isFinite && CLLocationCoordinate2DIsValid(info.coordinate) }
    private func lifetime(_ info: AirportInfo) -> TimeInterval { info.elevation != nil && info.use != nil ? 604800 : 3600 }
    private func publish(_ info: AirportInfo) {
        guard valid(info) else { return }
        if airports[info.code]?.latitude != info.latitude || airports[info.code]?.longitude != info.longitude { coordinateRevision &+= 1 }
        airports[info.code] = info; failed.remove(info.code)
        freshUntil[info.code] = (info.retrievedAt ?? Date()).addingTimeInterval(lifetime(info))
        if let data = try? JSONEncoder().encode(info) { UserDefaults.standard.set(data, forKey: "airportInfo-v3-" + info.code) }
    }
    private func fetch(_ codes: [String]) async {
        // One request per inventory for up to 40 airports, instead of two sequential
        // requests per airport. Publish FAA coordinates before waiting for details.
        for offset in stride(from: 0, to: codes.count, by: 40) {
            let chunk = Array(codes[offset..<min(offset + 40, codes.count)])
            async let primary = AirportDataService.faa(chunk)
            async let supplement = AirportDataService.dot(chunk)
            let faa = await primary
            for info in faa.values { publish(info) }
            let dot = await supplement
            for code in chunk {
                if let info = faa[code] ?? dot[code] { publish(AirportDataService.merge(info, dot[code])) }
            }
            let missing = chunk.filter { faa[$0] == nil && dot[$0] == nil }
            await withTaskGroup(of: (String, AirportInfo?).self) { group in
                var iterator = missing.makeIterator()
                for _ in 0..<min(4, missing.count) {
                    if let code = iterator.next() { group.addTask { (code, await AirportDataService.fallback(code)) } }
                }
                while let (code, fetched) = await group.next() {
                    if let fetched { publish(AirportDataService.merge(fetched, airports[code])) }
                    else { failed.insert(code) }
                    if let next = iterator.next() { group.addTask { (next, await AirportDataService.fallback(next)) } }
                }
            }
        }
    }
}

enum FleetGrouping: String, CaseIterable, Identifiable {
    case models = "Aircraft models"
    case variants = "Model variants"
    var id: String { rawValue }
    func countLabel(_ count: Int) -> String {
        switch self {
        case .models: return count == 1 ? "aircraft model" : "aircraft models"
        case .variants: return count == 1 ? "model variant" : "model variants"
        }
    }
}

struct FleetRangeGroup: Identifiable {
    let title: String
    let variants: [String]
    let flights: [Flight]
    var id: String { title.uppercased() }
    var total: Double { flights.reduce(0) { $0 + $1.total } }
}

enum FleetRange {
    static func groups(_ flights: [Flight], by grouping: FleetGrouping) -> [FleetRangeGroup] {
        let namedFlights = flights.filter { !$0.aircraftModel.isEmpty }
        let buckets = Dictionary(grouping: namedFlights) { flight in
            let name = grouping == .models ? AircraftNames.baseModel(flight.aircraftModel) : flight.aircraftModel
            return name.uppercased()
        }
        return buckets.values.compactMap { matches -> FleetRangeGroup? in
            guard let first = matches.first else { return nil }
            let variants = Dictionary(grouping: matches.map { $0.aircraftModel }, by: { $0.uppercased() })
                .values.compactMap { $0.sorted().first }.sorted()
            let title = grouping == .models ? AircraftNames.baseModel(first.aircraftModel) : variants.first ?? first.aircraftModel
            return FleetRangeGroup(title: title, variants: variants, flights: matches)
        }.sorted { a, b in
            a.total == b.total ? a.title.localizedStandardCompare(b.title) == .orderedAscending : a.total > b.total
        }
    }
}
